CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX ON sessions(user_id);
CREATE TABLE password_resets (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES accounts(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, created_by uuid NOT NULL REFERENCES accounts(id));
CREATE TABLE houses (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, address text NOT NULL, contact text NOT NULL DEFAULT '', profile jsonb, status text NOT NULL DEFAULT 'pending_review' CHECK(status IN ('pending_review','pilot_approved','suspended')), revision integer NOT NULL DEFAULT 0, ai_allowed boolean NOT NULL DEFAULT false);
CREATE TABLE premises (id uuid PRIMARY KEY, house_id uuid NOT NULL REFERENCES houses(id), number text NOT NULL, kind text NOT NULL DEFAULT 'Квартира', useful_area numeric(16,2), UNIQUE(house_id,kind,number));
CREATE TABLE memberships (id uuid PRIMARY KEY, house_id uuid NOT NULL REFERENCES houses(id), user_id uuid NOT NULL REFERENCES accounts(id), role text NOT NULL CHECK(role IN ('chair','resident')), premise_id uuid REFERENCES premises(id), UNIQUE(house_id,user_id));
CREATE TABLE invitations (id uuid PRIMARY KEY, token_hash text NOT NULL UNIQUE, house_id uuid NOT NULL REFERENCES houses(id), email text NOT NULL, role text NOT NULL CHECK(role IN ('chair','resident')), premise_number text NOT NULL DEFAULT '', created_by uuid NOT NULL REFERENCES accounts(id), expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz);
CREATE TABLE records (house_id uuid NOT NULL REFERENCES houses(id), collection text NOT NULL CHECK(collection IN ('tickets','docs','works','announcements','wizardDocuments')), id uuid NOT NULL, payload jsonb NOT NULL, version integer NOT NULL DEFAULT 1, PRIMARY KEY(house_id,collection,id));
CREATE INDEX ON records(house_id,collection);
CREATE TABLE messages (id uuid PRIMARY KEY, house_id uuid NOT NULL REFERENCES houses(id), ticket_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES accounts(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE record_versions (house_id uuid NOT NULL REFERENCES houses(id), collection text NOT NULL, record_id uuid NOT NULL, version integer NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(house_id,collection,record_id,version));
CREATE TABLE files (id uuid PRIMARY KEY, house_id uuid NOT NULL REFERENCES houses(id), record_collection text NOT NULL CHECK(record_collection IN ('tickets','docs')), record_id uuid NOT NULL, stored_name text NOT NULL UNIQUE, original_name text NOT NULL, mime text NOT NULL, bytes integer NOT NULL, extracted_text text NOT NULL DEFAULT '', extraction_status text NOT NULL, created_by uuid NOT NULL REFERENCES accounts(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit (id bigserial PRIMARY KEY, house_id uuid REFERENCES houses(id), user_id uuid REFERENCES accounts(id), action text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_usage (house_id uuid NOT NULL REFERENCES houses(id), month text NOT NULL, requests integer NOT NULL DEFAULT 0, PRIMARY KEY(house_id,month));
